      {
        rewrite <-DTL.beqAddrTrue in HbeqPdAddr. subst addr. unfold isPADDR in Hpaddr.
        rewrite HlookupPdAddrs0 in Hpaddr. exfalso; congruence.
      }
      rewrite <-beqAddrFalse in HbeqPdAddr. rewrite removeDupIdentity; intuition.
  }
