Lemma lookupPADDREqWriteAccessRev cutStatesList initState parentsList addr startaddr endaddr flag s partition:
isPDT partition initState
-> isPADDR addr s
-> isBuiltFromWriteAccessibleRec initState s cutStatesList parentsList partition startaddr endaddr flag
-> lookup addr (memory s) beqAddr = lookup addr (memory initState) beqAddr.
Proof.
revert parentsList. revert initState. revert partition. induction cutStatesList.
- (* cutStatesList = [] *)
  simpl.
  intros partition initState parentsList HlookupPartsInit Hshe Hprops.
  destruct Hprops as [HparentsList HssInitEq]. subst s. reflexivity.
- (* cutStatesList = a::l *)
  simpl.
  intros partition initState parentsList HlookupPartsInit Hpaddr Hprops.
  destruct Hprops as [pdAddr (newPdEntriesList & (HparentsList & (realMPU & (pdentryBase & (pdentryPdAddr &
                        (blockInParentPartitionAddr & (bentry & (newBentry & (s1 & (Hs1 & HpropsOr &
                        HnewB & HlookupBlocks0 & HlookupBlocks1 & HPFlagBlock & HstartBlock & HendBlock &
                        HpdIsPart & HblockMappedPdAddr & HlookupBases0 & HlookupBases1 & HlookupPdAddrs0 &
                        HlookupPdAddrs1 & HpdAddr & HbaseNotRoot & HisBuilt))))))))))].
  assert(HpdAddrIsPDTA: isPDT pdAddr a).
  {
    unfold isPDT. destruct HpropsOr as [Has1Eq | Ha].
    - subst a. rewrite HlookupPdAddrs1. trivial.
    - destruct Ha as [Ha HMPU]. rewrite Ha. simpl. rewrite beqAddrTrue. trivial.
  }
  specialize(IHcutStatesList pdAddr a newPdEntriesList HpdAddrIsPDTA Hpaddr HisBuilt). unfold isPADDR in *.
  rewrite IHcutStatesList in *.
  assert(HlookupEqA: lookup addr (memory a) beqAddr = lookup addr (memory s1) beqAddr).
  {
    destruct HpropsOr as [Has1Eq | Ha].
    + subst a. reflexivity.
    + destruct Ha as [Ha _]. rewrite Ha. rewrite Ha in Hpaddr. simpl in *.
      destruct (beqAddr pdAddr addr) eqn:HbeqPdAddr; try(exfalso; congruence).
      rewrite <-beqAddrFalse in HbeqPdAddr. rewrite removeDupIdentity; intuition.
  }
  rewrite HlookupEqA in *.
  rewrite Hs1. rewrite Hs1 in Hpaddr. simpl in *.
  destruct (beqAddr blockInParentPartitionAddr addr) eqn:HbeqBlockAddr; try(exfalso; congruence).
  rewrite <-beqAddrFalse in HbeqBlockAddr. rewrite removeDupIdentity; intuition.
Qed.

Lemma lookupSCEEqWriteAccess cutStatesList initState parentsList scentry startaddr endaddr flag s partition:
isPDT partition initState
-> isSCE scentry initState
-> isBuiltFromWriteAccessibleRec initState s cutStatesList parentsList partition startaddr endaddr flag
-> lookup scentry (memory s) beqAddr = lookup scentry (memory initState) beqAddr.
Proof.
revert parentsList. revert initState. revert partition. induction cutStatesList.
- (* cutStatesList = [] *)
  simpl.
  intros partition initState parentsList HlookupPartsInit Hsce Hprops.
  destruct Hprops as [HparentsList HssInitEq]. subst s. reflexivity.
- (* cutStatesList = a::l *)
  simpl.
  intros partition initState parentsList HlookupPartsInit Hsce Hprops.
  destruct Hprops as [pdAddr (newPdEntriesList & (HparentsList & (realMPU & (pdentryBase & (pdentryPdAddr &
                        (blockInParentPartitionAddr & (bentry & (newBentry & (s1 & (Hs1 & HpropsOr &
                        HnewB & HlookupBlocks0 & HlookupBlocks1 & HPFlagBlock & HstartBlock & HendBlock &
                        HpdIsPart & HblockMappedPdAddr & HlookupBases0 & HlookupBases1 & HlookupPdAddrs0 &
                        HlookupPdAddrs1 & HpdAddr & HbaseNotRoot & HisBuilt))))))))))].
  assert(HpdAddrIsPDTA: isPDT pdAddr a).
  {
    unfold isPDT. destruct HpropsOr as [Has1Eq | Ha].
    - subst a. rewrite HlookupPdAddrs1. trivial.
    - destruct Ha as [Ha HMPU]. rewrite Ha. simpl. rewrite beqAddrTrue. trivial.
  }
  assert(HlookupEqs1: lookup scentry (memory s1) beqAddr = lookup scentry (memory initState) beqAddr).
  {
    rewrite Hs1. simpl. destruct (beqAddr blockInParentPartitionAddr scentry) eqn:HbeqBlockSce.
    {
      rewrite <-DTL.beqAddrTrue in HbeqBlockSce. subst blockInParentPartitionAddr.
      unfold isSCE in Hsce. rewrite HlookupBlocks0 in Hsce. exfalso; congruence.
    }
    rewrite <-beqAddrFalse in HbeqBlockSce. rewrite removeDupIdentity; intuition.
  }
  assert(HlookupEqA: lookup scentry (memory a) beqAddr = lookup scentry (memory initState) beqAddr).
  {
    rewrite <-HlookupEqs1. destruct HpropsOr as [Has1Eq | Ha].
    + subst a. reflexivity.
    + destruct Ha as [Ha _]. rewrite Ha. simpl. destruct (beqAddr pdAddr scentry) eqn:HbeqPdSce.
      {
        rewrite <-DTL.beqAddrTrue in HbeqPdSce. subst scentry. unfold isSCE in Hsce.
        rewrite HlookupPdAddrs0 in Hsce. exfalso; congruence.
      }
      rewrite <-beqAddrFalse in HbeqPdSce. rewrite removeDupIdentity; intuition.
  }
  rewrite <-HlookupEqA.
  assert(HsceA: isSCE scentry a).
  {
    unfold isSCE in *. rewrite HlookupEqA. assumption.
  }
  specialize(IHcutStatesList pdAddr a newPdEntriesList HpdAddrIsPDTA HsceA HisBuilt).
  assumption.
Qed.

Lemma lookupSCEEqWriteAccessRev cutStatesList initState parentsList scentry startaddr endaddr flag s partition:
isSCE scentry s
-> isPDT partition initState
-> isBuiltFromWriteAccessibleRec initState s cutStatesList parentsList partition startaddr endaddr flag
-> lookup scentry (memory s) beqAddr = lookup scentry (memory initState) beqAddr.
Proof.
intro Hsce. revert parentsList. revert initState. revert partition. induction cutStatesList.
- (* cutStatesList = [] *)
  simpl.
  intros partition initState parentsList HlookupPartsInit Hprops.
  destruct Hprops as [HparentsList HssInitEq]. subst s. reflexivity.
- (* cutStatesList = a::l *)
  simpl.
  intros partition initState parentsList HlookupPartsInit Hprops.
  destruct Hprops as [pdAddr (newPdEntriesList & (HparentsList & (realMPU & (pdentryBase & (pdentryPdAddr &
                        (blockInParentPartitionAddr & (bentry & (newBentry & (s1 & (Hs1 & HpropsOr &
                        HnewB & HlookupBlocks0 & HlookupBlocks1 & HPFlagBlock & HstartBlock & HendBlock &
                        HpdIsPart & HblockMappedPdAddr & HlookupBases0 & HlookupBases1 & HlookupPdAddrs0 &
                        HlookupPdAddrs1 & HpdAddr & HbaseNotRoot & HisBuilt))))))))))].
  assert(HpdAddrIsPDTA: isPDT pdAddr a).
  {
    unfold isPDT. destruct HpropsOr as [Has1Eq | Ha].
    - subst a. rewrite HlookupPdAddrs1. trivial.
    - destruct Ha as [Ha HMPU]. rewrite Ha. simpl. rewrite beqAddrTrue. trivial.
  }
  specialize(IHcutStatesList pdAddr a newPdEntriesList HpdAddrIsPDTA HisBuilt). unfold isSCE in *.
  rewrite IHcutStatesList in *.
  assert(HlookupEqA: lookup scentry (memory a) beqAddr = lookup scentry (memory s1) beqAddr).
  {
    destruct HpropsOr as [Has1Eq | Ha].
    + subst a. reflexivity.
    + destruct Ha as [Ha _]. rewrite Ha. simpl. destruct (beqAddr pdAddr scentry) eqn:HbeqPdSce.
      {
        rewrite <-DTL.beqAddrTrue in HbeqPdSce. subst scentry. unfold isPDT in *. exfalso.
        destruct (lookup pdAddr (memory a) beqAddr); try(congruence). destruct v; congruence.
      }
      rewrite <-beqAddrFalse in HbeqPdSce. rewrite removeDupIdentity; intuition.
  }
  rewrite HlookupEqA in *. rewrite Hs1. simpl. destruct (beqAddr blockInParentPartitionAddr scentry) eqn:HbeqBlockSce.
  {
    rewrite <-DTL.beqAddrTrue in HbeqBlockSce. subst blockInParentPartitionAddr.
    rewrite HlookupBlocks1 in *. exfalso; congruence.
  }
  rewrite <-beqAddrFalse in HbeqBlockSce. rewrite removeDupIdentity; intuition.
Qed.

Lemma stablePDTIsBuilt statesList initState parentsList pdbasepartition startaddr endaddr flag s partition:
isPDT pdbasepartition initState
-> isBuiltFromWriteAccessibleRec initState s statesList parentsList pdbasepartition startaddr endaddr flag
-> isPDT partition initState
-> isPDT partition s.
Proof.
revert pdbasepartition. revert parentsList. revert initState. induction statesList.
- (* statesList = [] *)
  simpl.
  intros initState parentsList pdbasepartition HbaseIsPDTInit HisBuilt HpartIsPDTInit.
  destruct HisBuilt as [_ HssInitEq]. subst s. assumption.
- (* statesList = a::l *)
  simpl. intros initState parentsList pdbasepartition HbaseIsPDTInit HisBuilt HpartIsPDTInit.
  destruct HisBuilt as [pdAddr (newPdEntriesList & (HparentsList & (realMPU & (pdentryBase & (pdentryPdAddr &
                        (blockInParentPartitionAddr & (bentry & (newBentry & (s1 & (Hs1 & HpropsOr &
                        HnewB & HlookupBlocks0 & HlookupBlocks1 & HPFlagBlock & HstartBlock & HendBlock &
                        HpartIsPart & HblockMappedPdAddr & HlookupBases0 & HlookupBases1 & HlookupPdAddrs0 &
                        HlookupPdAddrs1 & HpdAddr & HbaseNotRoot & HisBuilt))))))))))].
  assert(HpdAddrIsPDTA: isPDT pdAddr a).
  {
    unfold isPDT. destruct HpropsOr as [Has1Eq | Ha].
    - subst a. rewrite HlookupPdAddrs1. trivial.
    - destruct Ha as [Ha HMPU]. rewrite Ha. simpl. rewrite beqAddrTrue. trivial.
  }
  assert(HpartIsPDTA: isPDT partition a).
  {
    assert(HpartIsPDTs1: isPDT partition s1).
    {
      unfold isPDT in *. rewrite Hs1. simpl.
