Lemma getFreeSlotsListRecEqBuiltWithWriteAcc n s0 s firstFree nidx statesList parentsList startaddr endaddr buildPart
  flag:
beqAddr firstFree nullAddr = false
-> wellFormedFreeSlotsList (getFreeSlotsListRec n firstFree s0 nidx) <> False
-> NoDup (filterOptionPaddr (getFreeSlotsListRec n firstFree s0 nidx))
-> (forall block, In (SomePaddr block) (getFreeSlotsListRec n firstFree s0 nidx) -> isFreeSlot block s0)
-> isBuiltFromWriteAccessibleRec s0 s statesList parentsList buildPart startaddr endaddr flag
-> getFreeSlotsListRec n firstFree s nidx = getFreeSlotsListRec n firstFree s0 nidx.
Proof.
intro HbeqFirstNull.
revert s0 parentsList buildPart. induction statesList; intros s0 parentsList buildPart HwellFormedFree HnoDupFree
  HfreeAreFree HisBuilt; simpl in HisBuilt; try(destruct HisBuilt; subst s; reflexivity).
destruct HisBuilt as [pdAddr (newPdEntriesList & (HparentsList & (realMPU & (pdentry0 & pdentry1 &
                      (blockInParentPartitionAddr & (bentry & (newBentry & (s1 & (Hs1 & (HpropsOr
                       & (HnewB & (HlookupBlocks0 & HlookupBlocks1 & HPFlag & HblockStart & HblockEnd &
                       HpdIsPart & HblockIsMapped & HlookupParentsInit & HlookupParents1 & HlookupAncestorsInit &
                       HlookupAncestors1 & Hancestor & HbaseNotRoot & HisBuilt))))))))))))].
assert(~ isFreeSlot blockInParentPartitionAddr s0).
{
  unfold isFreeSlot. unfold bentryPFlag in *. rewrite HlookupBlocks0 in *.
  destruct (lookup (CPaddr (blockInParentPartitionAddr + sh1offset)) (memory s0) beqAddr); try(intuition; congruence).
  destruct v; try(intuition; congruence).
  destruct (lookup (CPaddr (blockInParentPartitionAddr + scoffset)) (memory s0) beqAddr); try(intuition; congruence).
  destruct v; intuition; congruence.
}
assert(HfirstIsFree: isFreeSlot firstFree s0).
{
  apply HfreeAreFree. destruct n; simpl; simpl in HwellFormedFree; try(intuition; congruence).
  destruct (lookup firstFree (memory s0) beqAddr); try(intuition; congruence). rewrite HbeqFirstNull in *.
  destruct v; try(intuition; congruence). destruct (StateLib.Index.pred nidx); try(simpl in *; congruence).
  simpl. left. reflexivity.
}
assert(Heqs1: getFreeSlotsListRec n firstFree s1 nidx = getFreeSlotsListRec n firstFree s0 nidx).
{
  rewrite Hs1. apply getFreeSlotsListRecEqBE; trivial.
  - intro Hcontra. rewrite Hcontra in *. congruence.
  - unfold isBE. rewrite HlookupBlocks0. trivial.
  - intro Hcontra. apply optionIsInFilter in Hcontra. specialize(HfreeAreFree blockInParentPartitionAddr Hcontra).
    congruence.
}
assert(HeqA: getFreeSlotsListRec n firstFree a nidx = getFreeSlotsListRec n firstFree s0 nidx).
{
  rewrite <-Heqs1. destruct HpropsOr as [Has1Eq | Ha]; try(subst a; reflexivity).
  destruct Ha as [Ha _]. rewrite Ha. apply getFreeSlotsListRecEqPDT; unfold isBE; unfold isPADDR;
    try(rewrite HlookupAncestors1); try(intuition; congruence). intro Hcontra. rewrite Hcontra in *.
  unfold isFreeSlot in *. rewrite HlookupAncestorsInit in *. congruence.
}
rewrite <-HeqA in *. assert(HfreeAreFreeA: forall block,
   In (SomePaddr block) (getFreeSlotsListRec n firstFree a nidx) -> isFreeSlot block a).
{
  intros block HblockIn. specialize(HfreeAreFree block HblockIn).
  assert(Hblocks1: isFreeSlot block s1).
  {
    unfold isFreeSlot in *. rewrite Hs1. simpl. destruct (beqAddr blockInParentPartitionAddr block) eqn:HbeqBlocks.
    { rewrite <-DTL.beqAddrTrue in HbeqBlocks. subst block. exfalso; congruence. }
    rewrite <-beqAddrFalse in *. rewrite removeDupIdentity; try(apply not_eq_sym); trivial.
    destruct (lookup block (memory s0) beqAddr); try(congruence). destruct v; try(congruence).
    destruct (beqAddr blockInParentPartitionAddr (CPaddr (block + sh1offset))) eqn:HbeqBlockSh1.
    {
      rewrite <-DTL.beqAddrTrue in HbeqBlockSh1. rewrite HbeqBlockSh1 in *. rewrite HlookupBlocks0 in *. congruence.
    }
    rewrite <-beqAddrFalse in *. rewrite removeDupIdentity; try(apply not_eq_sym); trivial.
    destruct (lookup (CPaddr (block + sh1offset)) (memory s0) beqAddr); try(congruence). destruct v; try(congruence).
    destruct (beqAddr blockInParentPartitionAddr (CPaddr (block + scoffset))) eqn:HbeqBlockSce.
    {
      rewrite <-DTL.beqAddrTrue in HbeqBlockSce. rewrite HbeqBlockSce in *. rewrite HlookupBlocks0 in *. congruence.
    }
    rewrite <-beqAddrFalse in *. rewrite removeDupIdentity; try(apply not_eq_sym); trivial.
  }
  destruct HpropsOr as [Has1Eq | Ha]; try(subst a; assumption). destruct Ha as [Ha _]. unfold isFreeSlot in *.
  rewrite Ha. simpl. destruct (beqAddr pdAddr block) eqn:HbeqParentBlock.
  { rewrite <-DTL.beqAddrTrue in HbeqParentBlock. subst block. rewrite HlookupAncestors1 in *. congruence. }
  rewrite <-beqAddrFalse in *. rewrite removeDupIdentity; try(apply not_eq_sym); trivial.
  destruct (lookup block (memory s1) beqAddr); try(congruence). destruct v; try(congruence).
  destruct (beqAddr pdAddr (CPaddr (block + sh1offset))) eqn:HbeqParentSh1.
  {
    rewrite <-DTL.beqAddrTrue in HbeqParentSh1. rewrite HbeqParentSh1 in *. rewrite HlookupAncestors1 in *.
    congruence.
  }
  rewrite <-beqAddrFalse in *. rewrite removeDupIdentity; try(apply not_eq_sym); trivial.
  destruct (lookup (CPaddr (block + sh1offset)) (memory s1) beqAddr); try(congruence). destruct v; try(congruence).
  destruct (beqAddr pdAddr (CPaddr (block + scoffset))) eqn:HbeqParentSce.
  {
    rewrite <-DTL.beqAddrTrue in HbeqParentSce. rewrite HbeqParentSce in *. rewrite HlookupAncestors1 in *.
    congruence.
  }
  rewrite <-beqAddrFalse in *. rewrite removeDupIdentity; try(apply not_eq_sym); trivial.
}
specialize(IHstatesList a newPdEntriesList pdAddr HwellFormedFree HnoDupFree HfreeAreFreeA HisBuilt). assumption.
Qed.

Lemma getConfigBlocksEqBuiltWithWriteAcc part s0 s statesList parentsList buildPart startaddr endaddr flag:
isPDT part s0
-> isBuiltFromWriteAccessibleRec s0 s statesList parentsList buildPart startaddr endaddr flag
-> getConfigBlocks part s = getConfigBlocks part s0.
Proof.
revert s0 parentsList buildPart. induction statesList; simpl; intros s0 parentsList buildPart HpartIsPDT HisBuilt;
  try(destruct HisBuilt as (_ & HsEq); subst s0; reflexivity).
destruct HisBuilt as [pdAddr (newPdEntriesList & (HparentsList & (realMPU & (pdentry0 & pdentry1 &
                      (blockInParentPartitionAddr & (bentry & (newBentry & (s1 & (Hs1 & (HpropsOr
                       & (HnewB & (HlookupBlocks0 & HlookupBlocks1 & HPFlag & HblockStart & HblockEnd &
                       HpdIsPart & HblockIsMapped & HlookupParentsInit & HlookupParents1 & HlookupAncestorsInit &
                       HlookupAncestors1 & Hancestor & HbaseNotRoot & HisBuilt))))))))))))].
assert(HpartIsPDTs1: isPDT part s1).
{
  unfold isPDT in *. rewrite Hs1. simpl. destruct (beqAddr blockInParentPartitionAddr part) eqn:HbeqBlockPart.
  {
    rewrite <-DTL.beqAddrTrue in HbeqBlockPart. subst part. rewrite HlookupBlocks0 in *. congruence.
  }
  rewrite <-beqAddrFalse in *. rewrite removeDupIdentity; try(apply not_eq_sym); trivial.
}
assert(HpartIsPDTa: isPDT part a).
{
  destruct HpropsOr as [HA | (Ha & _)]; try(subst a; assumption). unfold isPDT in *. rewrite Ha. simpl.
  destruct (beqAddr pdAddr part) eqn:HbeqParentPart; trivial.
  rewrite <-beqAddrFalse in *. rewrite removeDupIdentity; try(apply not_eq_sym); trivial.
}
specialize(IHstatesList a newPdEntriesList pdAddr HpartIsPDTa HisBuilt). rewrite IHstatesList.
assert(Heqs1: getConfigBlocks part s1 = getConfigBlocks part s0).
{
  rewrite Hs1. apply getConfigBlocksEqBE; trivial. unfold isBE. rewrite HlookupBlocks0. trivial.
}
rewrite <-Heqs1. destruct HpropsOr as [HA | (Ha & _)]; try(subst a; reflexivity). rewrite Ha.
apply getConfigBlocksEqPDT with pdentry1; trivial.
Qed.

Lemma getAllPaddrConfigAuxEqBuiltWithWriteAcc kernList s s0 statesList parentsList buildPart startaddr
endaddr flag:
isBuiltFromWriteAccessibleRec s0 s statesList parentsList buildPart startaddr endaddr flag
-> getAllPaddrConfigAux kernList s = getAllPaddrConfigAux kernList s0.
Proof.
revert s0 parentsList buildPart. induction statesList; simpl; intros s0 parentsList buildPart HisBuilt;
  try(destruct HisBuilt as (_ & HsEq); subst s0; reflexivity).
destruct HisBuilt as [pdAddr (newPdEntriesList & (HparentsList & (realMPU & (pdentry0 & pdentry1 &
                      (blockInParentPartitionAddr & (bentry & (newBentry & (s1 & (Hs1 & (HpropsOr
                       & (HnewB & (HlookupBlocks0 & HlookupBlocks1 & HPFlag & HblockStart & HblockEnd &
                       HpdIsPart & HblockIsMapped & HlookupParentsInit & HlookupParents1 & HlookupAncestorsInit &
                       HlookupAncestors1 & Hancestor & HbaseNotRoot & HisBuilt))))))))))))].
assert(Heqs1: getAllPaddrConfigAux kernList s1 = getAllPaddrConfigAux kernList s0).
{
  rewrite Hs1. apply getAllPaddrConfigAuxEqBE. unfold isBE. rewrite HlookupBlocks0. trivial.
}
assert(Heqa: getAllPaddrConfigAux kernList a = getAllPaddrConfigAux kernList s0).
{
  rewrite <-Heqs1. destruct HpropsOr as [Ha | (Ha & _)]; rewrite Ha; trivial.
  apply getAllPaddrConfigAuxEqPDT. unfold isPDT. rewrite HlookupAncestors1. trivial.
}
rewrite <-Heqa. revert HisBuilt. apply IHstatesList.
Qed.

(* Partial consistency properties *)

Lemma currentPartitionEqIsBuilt partition statesList initState parentsList startaddr endaddr flag s:
isBuiltFromWriteAccessibleRec initState s statesList parentsList partition startaddr endaddr flag
-> currentPartition s = currentPartition initState.
Proof.
revert parentsList. revert partition. revert initState. induction statesList.
- (* statesList = [] *)
  intros initState partition parentsList HisBuilt. simpl in HisBuilt.
  destruct HisBuilt as [_ HsinitStateEq]. subst s. reflexivity.
- (* statesList = a::l *)
  intros initState partition parentsList HisBuilt. simpl in HisBuilt.
  destruct HisBuilt as [pdAddr (newPdEntriesList & (HparentsList & (realMPU & (pdentryBase & (pdentryParent &
                         (blockInParentPartitionAddr & (bentry & (newBentry & (s1 & (Hs1 & HpropsOr & HnewB &
                          HlookupBlockInit & HlookupBlocks1 & HPFlag & Hstart & Hend & HblockIsMapped &
                          HpdIsPart & HlookupPartInit & HlookupParts1 & HlookupParentInit & HlookupParents1 & Hparent
                          & HbaseNotRoot & HisBuilt))))))))))].
  specialize(IHstatesList a pdAddr newPdEntriesList HisBuilt).
  rewrite IHstatesList.
  assert(HcurrPartEq: currentPartition s1 = currentPartition initState).
  {
    rewrite Hs1. simpl. reflexivity.
  }
  destruct HpropsOr as [Has1Eq | Ha].
  + subst a. assumption.
  + destruct Ha as [Ha _]. rewrite Ha. simpl. assumption.
Qed.

Lemma getPartitionsEqIsBuilt s s1 s0 pdAddr pdentry1 blockInParentPartitionAddr bentry newMPU flag:
multiplexerIsPDT s0
-> wellFormedFstShadowIfBlockEntry s0
-> noDupPartitionTree s0
-> PDTIfPDFlag s0
-> lookup pdAddr (memory s0) beqAddr = Some (PDT pdentry1)
-> lookup blockInParentPartitionAddr (memory s0) beqAddr = Some (BE bentry)
-> (false = checkChild blockInParentPartitionAddr s0 (CPaddr (blockInParentPartitionAddr + sh1offset))
    \/ flag = false)
-> (s = s1
    \/
     s =
     {|
       currentPartition := currentPartition s1;
       memory :=
         add pdAddr
           (PDT
              {|
                structure := structure pdentry1;
                firstfreeslot := firstfreeslot pdentry1;
                nbfreeslots := nbfreeslots pdentry1;
                nbprepare := nbprepare pdentry1;
                parent := ADT.parent pdentry1;
                MPU := newMPU;
                vidtAddr := vidtAddr pdentry1
              |}) (memory s1) beqAddr
     |})
-> s1 =
      {|
        currentPartition := currentPartition s0;
        memory :=
          add blockInParentPartitionAddr
            (BE
               (CBlockEntry (read bentry) (write bentry) (exec bentry) (present bentry) flag
                  (blockindex bentry) (blockrange bentry))) (memory s0) beqAddr
      |}
-> getPartitions multiplexer s = getPartitions multiplexer s0.
Proof.
intros HmultIsPDT HwellSh1 HnoDupTree HPDTIfPDFlag HlookupPd HlookupBlock HflagProps HpropsOr Hs1.
assert(HlowerThanMax: blockindex bentry < kernelStructureEntriesNb) by (apply Hidx).
assert(HgetPartEq: getPartitions multiplexer s1 = getPartitions multiplexer s0).
{
  rewrite Hs1. unfold multiplexerIsPDT in HmultIsPDT.
  apply getPartitionsEqBEPDflagNoChangePresentNoChangeStartNoChange
       with bentry (CPaddr (blockInParentPartitionAddr + sh1offset));
     try(assumption);
     try(unfold CBlockEntry;
         destruct (Compare_dec.lt_dec (blockindex bentry) kernelStructureEntriesNb); try(lia);
         simpl; reflexivity).
  - unfold sh1entryAddr. rewrite HlookupBlock. reflexivity.
  - simpl. destruct (beqAddr blockInParentPartitionAddr (CPaddr (blockInParentPartitionAddr + sh1offset)))
          eqn:HbeqBlockBlockSh1.
    {
      assert(HblockIsBE: isBE blockInParentPartitionAddr s0) by (unfold isBE; rewrite HlookupBlock; trivial).
      specialize(HwellSh1 blockInParentPartitionAddr HblockIsBE).
      rewrite <-DTL.beqAddrTrue in HbeqBlockBlockSh1. rewrite <-HbeqBlockBlockSh1 in *.
      unfold isSHE in *. rewrite HlookupBlock in *. exfalso; congruence.
    }
    rewrite <-beqAddrFalse in HbeqBlockBlockSh1. rewrite removeDupIdentity; intuition.
  - unfold getPartitions. replace (maxAddr+2) with (S (maxAddr+1)); try(lia). simpl. auto.
}
rewrite <-HgetPartEq. destruct (beqAddr blockInParentPartitionAddr pdAddr) eqn:HbeqBlockPdAddr.
{
  rewrite <-DTL.beqAddrTrue in HbeqBlockPdAddr. rewrite HbeqBlockPdAddr in *.
  rewrite HlookupBlock in HlookupPd. exfalso; congruence.
}
assert(HlookupPdAddrs1: lookup pdAddr (memory s1) beqAddr = Some (PDT pdentry1)).
{
  rewrite Hs1. simpl. rewrite HbeqBlockPdAddr. rewrite <-beqAddrFalse in HbeqBlockPdAddr.
  rewrite removeDupIdentity; intuition.
}
destruct HpropsOr as [Hss1Eq | Hs]; try(subst s; reflexivity).
assert(HgetMappedEqs1: forall partition, getMappedBlocks partition s1 = getMappedBlocks partition s0).
{
  intro partition. rewrite Hs1.
  apply getMappedBlocksEqBENoChange with bentry; try(assumption);
        try(unfold CBlockEntry;
            destruct (Compare_dec.lt_dec (blockindex bentry) kernelStructureEntriesNb); try(lia);
            simpl; reflexivity).
}
rewrite Hs. apply getPartitionsEqPDT with pdentry1; trivial.
- unfold PDTIfPDFlag in *. intros idPDchild sh1entryaddr part HpartIsPart HblockMapped HcheckChild.
  assert(HcheckChilds0: true = checkChild idPDchild s0 sh1entryaddr
                        /\ sh1entryAddr idPDchild sh1entryaddr s0).
  {
    destruct HcheckChild as [HcheckChild Hsh1].
    unfold checkChild in *. unfold sh1entryAddr in *. rewrite Hs1 in HcheckChild. simpl in HcheckChild.
    rewrite Hs1 in Hsh1. simpl in Hsh1.
    destruct (beqAddr blockInParentPartitionAddr idPDchild) eqn:HbeqBlockIdChild.
    - rewrite <-DTL.beqAddrTrue in HbeqBlockIdChild. subst idPDchild. rewrite HlookupBlock.
      destruct (beqAddr blockInParentPartitionAddr sh1entryaddr) eqn:HbeqBlockSh1; try(exfalso; congruence).
      rewrite <-beqAddrFalse in HbeqBlockSh1. rewrite removeDupIdentity in HcheckChild; intuition.
    - rewrite <-beqAddrFalse in HbeqBlockIdChild. rewrite removeDupIdentity in Hsh1; try(intuition; congruence).
      rewrite removeDupIdentity in HcheckChild; try(intuition; congruence).
      destruct (lookup idPDchild (memory s0) beqAddr) eqn:HlookupIdPdChild; try(exfalso; congruence).
      destruct v; try(exfalso; congruence).
      destruct (beqAddr blockInParentPartitionAddr sh1entryaddr) eqn:HbeqBlockSh1;
            try(exfalso; congruence).
      rewrite <-beqAddrFalse in HbeqBlockSh1. rewrite removeDupIdentity in HcheckChild; intuition.
  }
  rewrite HgetPartEq in *. rewrite HgetMappedEqs1 in *.
  specialize(HPDTIfPDFlag idPDchild sh1entryaddr part HpartIsPart HblockMapped HcheckChilds0).
  destruct HPDTIfPDFlag as (HAFlag & HPFlag & [startaddr (Hstart & Hentry)]). unfold bentryAFlag in *.
  unfold bentryPFlag in *. unfold bentryStartAddr in *. unfold entryPDT in *.
  rewrite Hs1. simpl.
  destruct (beqAddr blockInParentPartitionAddr idPDchild) eqn:HbeqBlockIdChild.
  + rewrite <-DTL.beqAddrTrue in HbeqBlockIdChild. rewrite HbeqBlockIdChild in *.
    destruct HflagProps as [HPDFlagFalse | HflagFalse].
    * destruct HcheckChilds0 as (HcheckChilds0 & HchildSh1).
      unfold sh1entryAddr in HchildSh1. rewrite HlookupBlock in HchildSh1. subst sh1entryaddr.
      exfalso; congruence.
    * subst flag. unfold CBlockEntry.
      assert(blockindex bentry < kernelStructureEntriesNb) by (apply Hidx).
      destruct (Compare_dec.lt_dec (blockindex bentry) kernelStructureEntriesNb); try(lia). simpl.
      rewrite HlookupBlock in *. split. reflexivity. split. assumption. exists startaddr.
      split. assumption. destruct (beqAddr idPDchild (startAddr (blockrange bentry))) eqn:HbeqChildStart.
      {
        rewrite <-DTL.beqAddrTrue in HbeqChildStart. rewrite <-HbeqChildStart in *. rewrite HlookupBlock in *.
        congruence.
      }
      rewrite <-beqAddrFalse in HbeqChildStart. rewrite removeDupIdentity; try(apply not_eq_sym; assumption).
      assumption.
  + rewrite <-beqAddrFalse in HbeqBlockIdChild. rewrite removeDupIdentity; try(intuition; congruence).
    destruct (lookup idPDchild (memory s0) beqAddr) eqn:HlookupIdPdChild; try(exfalso; congruence).
    destruct v; try(exfalso; congruence).
    destruct (beqAddr blockInParentPartitionAddr (startAddr (blockrange b))) eqn:HbeqBlockStart.
    {
      rewrite <-DTL.beqAddrTrue in HbeqBlockStart. rewrite HbeqBlockStart in *.
      rewrite HlookupBlock in Hentry. exfalso; congruence.
    }
    rewrite <-beqAddrFalse in HbeqBlockStart. split. assumption. split. assumption. exists startaddr.
    split. assumption. rewrite removeDupIdentity; try(intuition; congruence).
- unfold noDupPartitionTree. rewrite HgetPartEq. assumption.
- unfold getPartitions. replace (maxAddr+2) with (S (maxAddr+1)); try(lia). simpl. auto.
Qed.

Lemma DisjointKSEntriesPreservedIsBuilt s s1 s0 pdAddr pdentry1 blockInParentPartitionAddr bentry newMPU flag:
multiplexerIsPDT s0
-> wellFormedFstShadowIfBlockEntry s0
-> noDupPartitionTree s0
-> PDTIfPDFlag s0
-> DisjointKSEntries s0
-> lookup pdAddr (memory s0) beqAddr = Some (PDT pdentry1)
-> lookup blockInParentPartitionAddr (memory s0) beqAddr = Some (BE bentry)
-> (false = checkChild blockInParentPartitionAddr s0 (CPaddr (blockInParentPartitionAddr + sh1offset))
    \/ flag = false)
-> (s = s1
    \/
     s =
     {|
       currentPartition := currentPartition s1;
       memory :=
         add pdAddr
           (PDT
              {|
                structure := structure pdentry1;
                firstfreeslot := firstfreeslot pdentry1;
                nbfreeslots := nbfreeslots pdentry1;
                nbprepare := nbprepare pdentry1;
                parent := ADT.parent pdentry1;
                MPU := newMPU;
                vidtAddr := vidtAddr pdentry1
              |}) (memory s1) beqAddr
     |})
-> s1 =
      {|
        currentPartition := currentPartition s0;
        memory :=
          add blockInParentPartitionAddr
            (BE
               (CBlockEntry (read bentry) (write bentry) (exec bentry) (present bentry) flag
                  (blockindex bentry) (blockrange bentry))) (memory s0) beqAddr
      |}
-> DisjointKSEntries s.
Proof.
intros HmultIsPDT HwellFormed HnoDupTree HPDTIfPDFlag Hdisjoint HlookupPdAddr HlookupBlock HPDFlagFalse
  HpropsOr Hs1.
assert(HlowerThanMax: blockindex bentry < kernelStructureEntriesNb) by (apply Hidx).
assert(HgetPartEq: getPartitions multiplexer s1 = getPartitions multiplexer s0).
{ revert Hs1. apply getPartitionsEqIsBuilt with pdAddr pdentry1 newMPU; auto. }
assert(HgetPartEqs: getPartitions multiplexer s = getPartitions multiplexer s0).
{ revert HpropsOr Hs1. apply getPartitionsEqIsBuilt; trivial. }
destruct (beqAddr blockInParentPartitionAddr pdAddr) eqn:HbeqBlockPdAddr.
{
  rewrite <-DTL.beqAddrTrue in HbeqBlockPdAddr. rewrite HbeqBlockPdAddr in *.
  rewrite HlookupBlock in HlookupPdAddr. exfalso; congruence.
}
assert(HlookupPdAddrs1: lookup pdAddr (memory s1) beqAddr = Some (PDT pdentry1)).
{
  rewrite Hs1. simpl. rewrite HbeqBlockPdAddr. rewrite <-beqAddrFalse in HbeqBlockPdAddr.
  rewrite removeDupIdentity; intuition.
}
unfold DisjointKSEntries in *. intros pd1 pd2 HisPDT1 HisPDT2 Hpd1NotPd2. rewrite HgetPartEqs in *.
specialize(Hdisjoint pd1 pd2 HisPDT1 HisPDT2 Hpd1NotPd2). rewrite <-HgetPartEq in *.
destruct Hdisjoint as [optionEntriesList1 (optionEntriesList2 & (Hlist1 & Hlist2 & Hdisjoint))].
exists optionEntriesList1. exists optionEntriesList2.
split. subst optionEntriesList1. destruct HpropsOr as [Hss1Eq | Hs].
{
  subst s. apply eq_sym. rewrite Hs1. apply getKSEntriesEqBE. unfold isBE. rewrite HlookupBlock. trivial.
}
{
  assert(HgetKSEq: getKSEntries pd1 s = getKSEntries pd1 s1).
  {
    rewrite Hs. apply getKSEntriesEqPDT with pdentry1; try(assumption). unfold CBlockEntry.
    destruct (Compare_dec.lt_dec (blockindex bentry) kernelStructureEntriesNb); try(lia). simpl. reflexivity.
  }
  rewrite HgetKSEq. apply eq_sym. rewrite Hs1. apply getKSEntriesEqBE. unfold isBE. rewrite HlookupBlock.
  trivial.
}
split. subst optionEntriesList2. destruct HpropsOr as [Hss1Eq | Hs].
{
  subst s. apply eq_sym. rewrite Hs1. apply getKSEntriesEqBE. unfold isBE. rewrite HlookupBlock. trivial.
}
{
  assert(HgetKSEq: getKSEntries pd2 s = getKSEntries pd2 s1).
  {
    rewrite Hs.
    apply getKSEntriesEqPDT with pdentry1; try(assumption). unfold CBlockEntry.
    destruct (Compare_dec.lt_dec (blockindex bentry) kernelStructureEntriesNb); try(lia). simpl. reflexivity.
  }
  rewrite HgetKSEq. apply eq_sym. rewrite Hs1. apply getKSEntriesEqBE. unfold isBE. rewrite HlookupBlock.
  trivial.
}
assumption.
Qed.

Lemma StructurePointerIsKSPreservedIsBuilt s s1 s0 pdAddr pdentry1 blockInParentPartitionAddr bentry newMPU flag:
multiplexerIsPDT s0
-> wellFormedFstShadowIfBlockEntry s0
-> noDupPartitionTree s0
-> PDTIfPDFlag s0
-> StructurePointerIsKS s0
-> lookup pdAddr (memory s0) beqAddr = Some (PDT pdentry1)
-> lookup blockInParentPartitionAddr (memory s0) beqAddr = Some (BE bentry)
-> (false = checkChild blockInParentPartitionAddr s0 (CPaddr (blockInParentPartitionAddr + sh1offset))
    \/ flag = false)
-> (s = s1
    \/
     s =
     {|
       currentPartition := currentPartition s1;
       memory :=
         add pdAddr
           (PDT
              {|
                structure := structure pdentry1;
                firstfreeslot := firstfreeslot pdentry1;
                nbfreeslots := nbfreeslots pdentry1;
                nbprepare := nbprepare pdentry1;
                parent := ADT.parent pdentry1;
                MPU := newMPU;
                vidtAddr := vidtAddr pdentry1
              |}) (memory s1) beqAddr
     |})
-> s1 =
      {|
        currentPartition := currentPartition s0;
        memory :=
          add blockInParentPartitionAddr
            (BE
               (CBlockEntry (read bentry) (write bentry) (exec bentry) (present bentry) flag
                  (blockindex bentry) (blockrange bentry))) (memory s0) beqAddr
      |}
-> StructurePointerIsKS s.
Proof.
intros HmultIsPDT HwellFormed HnoDupTree HPDTIfPDFlag Hstruct HlookupPdAddr HlookupBlock HflagOr HpropsOr Hs1.
assert(HgetPartEq: getPartitions multiplexer s1 = getPartitions multiplexer s0).
{ revert Hs1. apply getPartitionsEqIsBuilt with pdAddr pdentry1 newMPU; auto. }
assert(HgetPartEqs: getPartitions multiplexer s = getPartitions multiplexer s0).
{ revert HpropsOr Hs1. apply getPartitionsEqIsBuilt; trivial. }
assert(HlowerThanMax: blockindex bentry < kernelStructureEntriesNb) by (apply Hidx).
assert(Hstructs1: StructurePointerIsKS s1).
{
  unfold StructurePointerIsKS in *. intros entryaddr pdentry HentryIsPart HlookupEntry HstructNotNull.
  rewrite HgetPartEq in *.
  assert(HlookupEntrysInit: lookup entryaddr (memory s0) beqAddr = Some (PDT pdentry)).
  {
    rewrite Hs1 in HlookupEntry. simpl in HlookupEntry.
    destruct (beqAddr blockInParentPartitionAddr entryaddr) eqn:HbeqBlockEntry; try(exfalso; congruence).
    rewrite <-beqAddrFalse in HbeqBlockEntry. rewrite removeDupIdentity in HlookupEntry; intuition.
  }
  specialize(Hstruct entryaddr pdentry HentryIsPart HlookupEntrysInit HstructNotNull). rewrite Hs1. unfold isKS in *.
  simpl. destruct (beqAddr blockInParentPartitionAddr (structure pdentry)) eqn:HbeqBlockStruct.
  - rewrite <-DTL.beqAddrTrue in HbeqBlockStruct. rewrite HbeqBlockStruct in *.
    rewrite HlookupBlock in Hstruct. rewrite <-Hstruct. unfold CBlockEntry.
    destruct (Compare_dec.lt_dec (blockindex bentry) kernelStructureEntriesNb); try(lia). simpl. reflexivity.
  - rewrite <-beqAddrFalse in HbeqBlockStruct. rewrite removeDupIdentity; intuition.
}
destruct (beqAddr blockInParentPartitionAddr pdAddr) eqn:HbeqBlockPdAddr.
{
  rewrite <-DTL.beqAddrTrue in HbeqBlockPdAddr. rewrite HbeqBlockPdAddr in *.
  rewrite HlookupBlock in HlookupPdAddr. exfalso; congruence.
}
assert(HlookupPdAddrs1: lookup pdAddr (memory s1) beqAddr = Some (PDT pdentry1)).
{
  rewrite Hs1. simpl. rewrite HbeqBlockPdAddr. rewrite <-beqAddrFalse in HbeqBlockPdAddr.
  rewrite removeDupIdentity; intuition.
}
destruct HpropsOr as [Hss1Eq | Hs].
- subst s. assumption.
- intros entryaddr pdentry HentryIsPart HlookupEntry HstructNotNull.
  assert(HgetMappedEqs1: forall partition, getMappedBlocks partition s1 = getMappedBlocks partition s0).
  {
    intro partition. rewrite Hs1.
    apply getMappedBlocksEqBENoChange with bentry; try(assumption);
          try(unfold CBlockEntry;
              destruct (Compare_dec.lt_dec (blockindex bentry) kernelStructureEntriesNb); try(lia);
              simpl; reflexivity).
  }
  assert(HPDTIfPDFlags1: PDTIfPDFlag s1).
  {
    unfold PDTIfPDFlag in *. intros idPDchild sh1entryaddr part HpartIsPart HblockMapped HcheckChild.
    assert(HcheckChilds0: true = checkChild idPDchild s0 sh1entryaddr
                          /\ sh1entryAddr idPDchild sh1entryaddr s0).
    {
      destruct HcheckChild as [HcheckChild Hsh1].
      unfold checkChild in *. unfold sh1entryAddr in *. rewrite Hs1 in HcheckChild. simpl in HcheckChild.
      rewrite Hs1 in Hsh1. simpl in Hsh1.
      destruct (beqAddr blockInParentPartitionAddr idPDchild) eqn:HbeqBlockIdChild.
      - rewrite <-DTL.beqAddrTrue in HbeqBlockIdChild. subst idPDchild. rewrite HlookupBlock.
        destruct (beqAddr blockInParentPartitionAddr sh1entryaddr) eqn:HbeqBlockSh1; try(exfalso; congruence).
        rewrite <-beqAddrFalse in HbeqBlockSh1. rewrite removeDupIdentity in HcheckChild; intuition.
      - rewrite <-beqAddrFalse in HbeqBlockIdChild. rewrite removeDupIdentity in Hsh1; try(intuition; congruence).
        rewrite removeDupIdentity in HcheckChild; try(intuition; congruence).
        destruct (lookup idPDchild (memory s0) beqAddr) eqn:HlookupIdPdChild; try(exfalso; congruence).
        destruct v; try(exfalso; congruence).
        destruct (beqAddr blockInParentPartitionAddr sh1entryaddr) eqn:HbeqBlockSh1;
              try(exfalso; congruence).
        rewrite <-beqAddrFalse in HbeqBlockSh1. rewrite removeDupIdentity in HcheckChild; intuition.
    }
    rewrite HgetPartEq in *. rewrite HgetMappedEqs1 in *.
    specialize(HPDTIfPDFlag idPDchild sh1entryaddr part HpartIsPart HblockMapped HcheckChilds0).
    destruct HPDTIfPDFlag as (HAFlag & HPFlag & [startaddr (Hstart & Hentry)]). unfold bentryAFlag in *.
    unfold bentryPFlag in *. unfold bentryStartAddr in *. unfold entryPDT in *.
    rewrite Hs1. simpl.
    destruct (beqAddr blockInParentPartitionAddr idPDchild) eqn:HbeqBlockIdChild.
    - rewrite <-DTL.beqAddrTrue in HbeqBlockIdChild. rewrite HbeqBlockIdChild in *.
      destruct HflagOr as [HPDFlagFalse | HflagFalse].
      + destruct HcheckChilds0 as (HcheckChilds0 & HchildSh1).
        unfold sh1entryAddr in HchildSh1. rewrite HlookupBlock in HchildSh1. subst sh1entryaddr.
        exfalso; congruence.
      + subst flag. unfold CBlockEntry.
        assert(blockindex bentry < kernelStructureEntriesNb) by (apply Hidx).
        destruct (Compare_dec.lt_dec (blockindex bentry) kernelStructureEntriesNb); try(lia). simpl.
        rewrite HlookupBlock in *. split. reflexivity. split. assumption. exists startaddr.
        split. assumption. destruct (beqAddr idPDchild (startAddr (blockrange bentry))) eqn:HbeqChildStart.
        {
          rewrite <-DTL.beqAddrTrue in HbeqChildStart. rewrite <-HbeqChildStart in *. rewrite HlookupBlock in *.
          congruence.
        }
        rewrite <-beqAddrFalse in HbeqChildStart. rewrite removeDupIdentity; try(apply not_eq_sym; assumption).
        assumption.
    - rewrite <-beqAddrFalse in HbeqBlockIdChild. rewrite removeDupIdentity; try(intuition; congruence).
      destruct (lookup idPDchild (memory s0) beqAddr) eqn:HlookupIdPdChild; try(exfalso; congruence).
      destruct v; try(exfalso; congruence).
      destruct (beqAddr blockInParentPartitionAddr (startAddr (blockrange b))) eqn:HbeqBlockStart.
      {
        rewrite <-DTL.beqAddrTrue in HbeqBlockStart. rewrite HbeqBlockStart in *.
        rewrite HlookupBlock in Hentry. exfalso; congruence.
      }
      rewrite <-beqAddrFalse in HbeqBlockStart. split. assumption. split. assumption. exists startaddr.
      split. assumption. rewrite removeDupIdentity; try(intuition; congruence).
  }
  assert(HlookupEntrys1: exists pdentrys1, lookup entryaddr (memory s1) beqAddr = Some (PDT pdentrys1)
                                           /\ structure pdentrys1 = structure pdentry).
  {
    rewrite Hs in HlookupEntry. simpl in HlookupEntry.
    destruct (beqAddr pdAddr entryaddr) eqn:HbeqPdaddrEntry.
    + rewrite <-DTL.beqAddrTrue in HbeqPdaddrEntry. rewrite HbeqPdaddrEntry in *.
      rewrite HlookupPdAddrs1. exists pdentry1. injection HlookupEntry as HpdentriesEq.
      rewrite <-HpdentriesEq. simpl. split. reflexivity. reflexivity.
    + rewrite <-beqAddrFalse in HbeqPdaddrEntry. exists pdentry.
      rewrite removeDupIdentity in HlookupEntry; intuition.
  }
  destruct HlookupEntrys1 as [pdentrys1 (HlookupEntrys1 & HstructEq)]. rewrite HgetPartEqs in *.
  rewrite <-HgetPartEq in *. rewrite <-HstructEq in HstructNotNull.
  specialize(Hstructs1 entryaddr pdentrys1 HentryIsPart HlookupEntrys1 HstructNotNull).
  rewrite <-HstructEq. unfold isKS in *. rewrite Hs. simpl.
  destruct (beqAddr pdAddr (structure pdentrys1)) eqn:HbeqPdaddrStruct.
  {
    rewrite <-DTL.beqAddrTrue in HbeqPdaddrStruct. rewrite HbeqPdaddrStruct in *.
    rewrite HlookupPdAddrs1 in Hstructs1. congruence.
  }
  rewrite <-beqAddrFalse in HbeqPdaddrStruct. rewrite removeDupIdentity; auto.
Qed.

Lemma wellFormedFstShadowIfBlockEntryPreservedIsBuilt s s1 s0 pdAddr pdentry1 blockInParentPartitionAddr bentry
newMPU flag:
wellFormedFstShadowIfBlockEntry s0
-> lookup pdAddr (memory s0) beqAddr = Some (PDT pdentry1)
-> lookup blockInParentPartitionAddr (memory s0) beqAddr = Some (BE bentry)
-> (s = s1
    \/
     s =
     {|
       currentPartition := currentPartition s1;
       memory :=
         add pdAddr
           (PDT
              {|
                structure := structure pdentry1;
                firstfreeslot := firstfreeslot pdentry1;
                nbfreeslots := nbfreeslots pdentry1;
                nbprepare := nbprepare pdentry1;
                parent := ADT.parent pdentry1;
                MPU := newMPU;
                vidtAddr := vidtAddr pdentry1
              |}) (memory s1) beqAddr
     |})
-> s1 =
      {|
        currentPartition := currentPartition s0;
        memory :=
          add blockInParentPartitionAddr
            (BE
               (CBlockEntry (read bentry) (write bentry) (exec bentry) (present bentry) flag
                  (blockindex bentry) (blockrange bentry))) (memory s0) beqAddr
