            (BE
               (CBlockEntry (read bentry) (write bentry) (exec bentry) (present bentry) flag
                  (blockindex bentry) (blockrange bentry))) (memory s0) beqAddr
      |}
-> multiplexerIsPDT s.
Proof.
intros HmultPDT HlookupPdAddr HlookupBlock HpropsOr Hs1.
assert(HmultIsPDTA: multiplexerIsPDT s1).
{
  unfold multiplexerIsPDT in *. unfold isPDT in *. rewrite Hs1. simpl.
  destruct (beqAddr blockInParentPartitionAddr multiplexer) eqn:HbeqBlockMult.
  {
    rewrite <-DTL.beqAddrTrue in HbeqBlockMult. rewrite HbeqBlockMult in *.
    rewrite HlookupBlock in HmultPDT. congruence.
  }
  rewrite <-beqAddrFalse in HbeqBlockMult. rewrite removeDupIdentity; intuition.
}
destruct HpropsOr as [Hss1Eq | Hs].
+ (* s = s1 *)
  rewrite Hss1Eq. assumption.
+ (* s <> s1 *)
  unfold multiplexerIsPDT in *. unfold isPDT in *. rewrite Hs. simpl.
  destruct (beqAddr pdAddr multiplexer) eqn:HbeqPdAddrMult; try(trivial).
  rewrite <-beqAddrFalse in HbeqPdAddrMult. rewrite removeDupIdentity; intuition.
Qed.

Lemma PDTIfPDFlagPreservedIsBuilt s s1 s0 pdAddr pdentry1 blockInParentPartitionAddr bentry newMPU
flag:
PDTIfPDFlag s0
-> multiplexerIsPDT s0
-> wellFormedFstShadowIfBlockEntry s0
-> noDupPartitionTree s0
-> lookup pdAddr (memory s0) beqAddr = Some (PDT pdentry1)
-> lookup blockInParentPartitionAddr (memory s0) beqAddr = Some (BE bentry)
-> (false = checkChild blockInParentPartitionAddr s0 (CPaddr (blockInParentPartitionAddr + sh1offset))
    \/ flag = false)
-> (s = s1
    \/
     s =
     {|
       currentPartition := currentPartition s1;
       memory :=
         add pdAddr
           (PDT
              {|
                structure := structure pdentry1;
                firstfreeslot := firstfreeslot pdentry1;
                nbfreeslots := nbfreeslots pdentry1;
                nbprepare := nbprepare pdentry1;
                parent := ADT.parent pdentry1;
                MPU := newMPU;
                vidtAddr := vidtAddr pdentry1
              |}) (memory s1) beqAddr
     |})
-> s1 =
      {|
        currentPartition := currentPartition s0;
        memory :=
          add blockInParentPartitionAddr
            (BE
               (CBlockEntry (read bentry) (write bentry) (exec bentry) (present bentry) flag
                  (blockindex bentry) (blockrange bentry))) (memory s0) beqAddr
      |}
-> PDTIfPDFlag s.
Proof.
intros HPDTIfPDFlag HmultIsPDT HwellFormed HnoDupTree HlookupPdAddr HlookupBlock HPDFlagFalse HpropsOr Hs1.
assert(HgetPartEq: getPartitions multiplexer s1 = getPartitions multiplexer s0).
{ revert Hs1. apply getPartitionsEqIsBuilt with pdAddr pdentry1 newMPU; auto. }
assert(HgetPartEqs: getPartitions multiplexer s = getPartitions multiplexer s0).
{ revert HpropsOr Hs1. apply getPartitionsEqIsBuilt; trivial. }
assert(HlowerThanMax: blockindex bentry < kernelStructureEntriesNb) by (apply Hidx).
assert(HgetMappedEqs1: forall partition, getMappedBlocks partition s1 = getMappedBlocks partition s0).
{
  intro partition. rewrite Hs1.
  apply getMappedBlocksEqBENoChange with bentry; try(assumption);
        try(unfold CBlockEntry;
            destruct (Compare_dec.lt_dec (blockindex bentry) kernelStructureEntriesNb); try(lia);
            simpl; reflexivity).
}
assert(HPDTIfPDFlags1: PDTIfPDFlag s1).
{
  unfold PDTIfPDFlag in *. intros idPDchild sh1entryaddr part HpartIsPart HblockMapped HcheckChild.
  rewrite HgetPartEq in *. rewrite HgetMappedEqs1 in *.
  assert(HcheckChilds0: true = checkChild idPDchild s0 sh1entryaddr
                        /\ sh1entryAddr idPDchild sh1entryaddr s0).
  {
    destruct HcheckChild as [HcheckChild Hsh1].
    unfold checkChild in *. unfold sh1entryAddr in *. rewrite Hs1 in HcheckChild. simpl in HcheckChild.
    rewrite Hs1 in Hsh1. simpl in Hsh1.
    destruct (beqAddr blockInParentPartitionAddr idPDchild) eqn:HbeqBlockIdChild.
    - rewrite <-DTL.beqAddrTrue in HbeqBlockIdChild. subst idPDchild. rewrite HlookupBlock.
      destruct (beqAddr blockInParentPartitionAddr sh1entryaddr) eqn:HbeqBlockSh1; try(exfalso; congruence).
      rewrite <-beqAddrFalse in HbeqBlockSh1. rewrite removeDupIdentity in HcheckChild; intuition.
    - rewrite <-beqAddrFalse in HbeqBlockIdChild. rewrite removeDupIdentity in Hsh1; try(intuition; congruence).
      rewrite removeDupIdentity in HcheckChild; try(intuition; congruence).
      destruct (lookup idPDchild (memory s0) beqAddr) eqn:HlookupIdPdChild; try(exfalso; congruence).
      destruct v; try(exfalso; congruence).
      destruct (beqAddr blockInParentPartitionAddr sh1entryaddr) eqn:HbeqBlockSh1;
            try(exfalso; congruence).
      rewrite <-beqAddrFalse in HbeqBlockSh1. rewrite removeDupIdentity in HcheckChild; intuition.
  }
  specialize(HPDTIfPDFlag idPDchild sh1entryaddr part HpartIsPart HblockMapped HcheckChilds0).
  destruct HPDTIfPDFlag as (HAFlag & HPFlag & [startaddr (Hstart & Hentry)]). unfold bentryAFlag in *.
  unfold bentryPFlag in *. unfold bentryStartAddr in *. unfold entryPDT in *.
  rewrite Hs1. simpl.
  destruct (beqAddr blockInParentPartitionAddr idPDchild) eqn:HbeqBlockIdChild.
  - rewrite <-DTL.beqAddrTrue in HbeqBlockIdChild. rewrite HbeqBlockIdChild in *.
    destruct HPDFlagFalse as [HPDFlagFalse | HflagFalse].
    + destruct HcheckChilds0 as [HcheckChilds0 HchildSh1].
      unfold sh1entryAddr in HchildSh1. rewrite HlookupBlock in HchildSh1. subst sh1entryaddr.
      rewrite <-HcheckChilds0 in HPDFlagFalse. exfalso; congruence.
    + subst flag. unfold CBlockEntry. assert(blockindex bentry < kernelStructureEntriesNb) by (apply Hidx).
      destruct (Compare_dec.lt_dec (blockindex bentry) kernelStructureEntriesNb); try(lia). simpl.
      rewrite HlookupBlock in *. split. reflexivity. split. assumption. exists startaddr.
      split. assumption. destruct (beqAddr idPDchild (startAddr (blockrange bentry))) eqn:HbeqChildStart.
      {
        rewrite <-DTL.beqAddrTrue in HbeqChildStart. rewrite <-HbeqChildStart in *. rewrite HlookupBlock in *.
        congruence.
      }
      rewrite <-beqAddrFalse in HbeqChildStart. rewrite removeDupIdentity; try(apply not_eq_sym; assumption).
      assumption.
  - rewrite <-beqAddrFalse in HbeqBlockIdChild. rewrite removeDupIdentity; try(intuition; congruence).
    destruct (lookup idPDchild (memory s0) beqAddr) eqn:HlookupIdPdChild; try(exfalso; congruence).
    destruct v; try(exfalso; congruence).
    destruct (beqAddr blockInParentPartitionAddr (startAddr (blockrange b))) eqn:HbeqBlockStart.
    {
      rewrite <-DTL.beqAddrTrue in HbeqBlockStart. rewrite HbeqBlockStart in *.
      rewrite HlookupBlock in Hentry. exfalso; congruence.
    }
    rewrite <-beqAddrFalse in HbeqBlockStart. split. assumption. split. assumption. exists startaddr.
    split. assumption. rewrite removeDupIdentity; try(intuition; congruence).
}
destruct (beqAddr blockInParentPartitionAddr pdAddr) eqn:HbeqBlockPdAddr.
{
  rewrite <-DTL.beqAddrTrue in HbeqBlockPdAddr. rewrite HbeqBlockPdAddr in *.
  rewrite HlookupBlock in HlookupPdAddr. exfalso; congruence.
}
assert(HlookupPdAddrs1: lookup pdAddr (memory s1) beqAddr = Some (PDT pdentry1)).
{
  rewrite Hs1. simpl. rewrite HbeqBlockPdAddr. rewrite <-beqAddrFalse in HbeqBlockPdAddr.
  rewrite removeDupIdentity; intuition.
}
destruct HpropsOr as [Hss1Eq | Hs]; try(subst s; assumption).
unfold PDTIfPDFlag in *. intros idPDchild sh1entryaddr part HpartIsPart HblockMapped HcheckChild.
assert(HgetMappedEq: forall partition, In partition (getPartitions multiplexer s1)
  -> getMappedBlocks partition s = getMappedBlocks partition s1).
{
  intros partition HpartBIsPart. rewrite Hs. apply getMappedBlocksEqPDT with pdentry1; try(assumption).
  simpl. reflexivity.
}
rewrite HgetPartEqs in *. rewrite <-HgetPartEq in *. rewrite HgetMappedEq in *; trivial.
assert(HcheckChilds1: true = checkChild idPDchild s1 sh1entryaddr
                      /\ sh1entryAddr idPDchild sh1entryaddr s1).
{
  destruct HcheckChild as [HcheckChild Hsh1].
  unfold checkChild in *. unfold sh1entryAddr in *. rewrite Hs in HcheckChild. simpl in HcheckChild.
  rewrite Hs in Hsh1. simpl in Hsh1.
  destruct (beqAddr pdAddr idPDchild) eqn:HbeqPdAddrChild; try(exfalso; congruence).
  rewrite <-beqAddrFalse in HbeqPdAddrChild. rewrite removeDupIdentity in Hsh1; try(intuition; congruence).
  rewrite removeDupIdentity in HcheckChild; try(intuition; congruence).
  destruct (lookup idPDchild (memory s1) beqAddr) eqn:HlookupIdPdChild; try(exfalso; congruence).
  destruct v; try(exfalso; congruence).
  destruct (beqAddr pdAddr sh1entryaddr) eqn:HbeqBlockSh1; try(exfalso; congruence).
  rewrite <-beqAddrFalse in HbeqBlockSh1. rewrite removeDupIdentity in HcheckChild; intuition.
}
specialize(HPDTIfPDFlags1 idPDchild sh1entryaddr part HpartIsPart HblockMapped HcheckChilds1).
destruct HPDTIfPDFlags1 as (HAFlag & HPFlag & [startaddr (Hstart & Hentry)]). unfold bentryAFlag in *.
unfold bentryPFlag in *. unfold bentryStartAddr in *. unfold entryPDT in *.
rewrite Hs. simpl.
destruct (beqAddr pdAddr idPDchild) eqn:HbeqPdaddrChild.
{
  rewrite <-DTL.beqAddrTrue in HbeqPdaddrChild. rewrite HbeqPdaddrChild in *.
  rewrite HlookupPdAddrs1 in Hstart. exfalso; congruence.
}
rewrite <-beqAddrFalse in HbeqPdaddrChild. rewrite removeDupIdentity; auto. split; trivial. split; trivial.
destruct (lookup idPDchild (memory s1) beqAddr) eqn:HlookupIdChilds1; try(exfalso; congruence).
destruct v; try(exfalso; congruence). exists (startAddr (blockrange b)). split. reflexivity.
destruct (beqAddr pdAddr (startAddr (blockrange b))) eqn:HbeqPdAddrStart; try(reflexivity).
rewrite <-beqAddrFalse in HbeqPdAddrStart. rewrite removeDupIdentity; auto.
destruct (lookup (startAddr (blockrange b)) (memory s1) beqAddr); try(exfalso; congruence).
destruct v; try(exfalso; congruence). reflexivity.
Qed.

Lemma StructurePointerIsKSPreservedIsBuiltRec s s0 statesList parentsList buildPart startaddr endaddr flag:
multiplexerIsPDT s0
-> wellFormedFstShadowIfBlockEntry s0
-> noDupPartitionTree s0
-> PDTIfPDFlag s0
-> StructurePointerIsKS s0
-> (~isPDT startaddr s0 \/ flag = false)
-> isBuiltFromWriteAccessibleRec s0 s statesList parentsList buildPart startaddr endaddr flag
-> StructurePointerIsKS s.
Proof.
revert s0. revert parentsList. revert buildPart. induction statesList; simpl;
  intros buildPart parentsList s0 HmultIsPDT HwellSh1 HnoDupTree HPDTIfPDFlag Hstruct HflagProps HisBuilt.
- destruct HisBuilt as [_ Hss0Eq]. subst s. intuition.
- destruct HisBuilt as [pdAddr (newPdEntriesList & (HparentsList & (realMPU & (pdentry0 & pdentry1 &
                      (blockInParentPartitionAddr & (bentry & (newBentry & (s1 & (Hs1 & (HpropsOr
                       & (HnewB & (HlookupBlocks0 & HlookupBlocks1 & HPFlag & HblockStart & HblockEnd &
                       HpdIsPart & HblockIsMapped & HlookupParentsInit & HlookupParents1 & HlookupAncestorsInit &
                       HlookupAncestors1 & Hancestor & HbaseNotRoot & HisBuilt))))))))))))].
  assert(HflagPropsB: false = checkChild blockInParentPartitionAddr s0 (CPaddr (blockInParentPartitionAddr+sh1offset))
    \/ flag = false).
  {
    destruct HflagProps as [HstartNotPDT | HflagFalse]; auto. left.
    destruct (checkChild blockInParentPartitionAddr s0 (CPaddr (blockInParentPartitionAddr+sh1offset)))
      eqn:HcheckChild; trivial. exfalso.
    assert(Hchild: true = checkChild blockInParentPartitionAddr s0 (CPaddr (blockInParentPartitionAddr+sh1offset))
      /\ sh1entryAddr blockInParentPartitionAddr (CPaddr (blockInParentPartitionAddr+sh1offset)) s0).
    { split; auto. unfold sh1entryAddr. rewrite HlookupBlocks0. reflexivity. }
    specialize(HPDTIfPDFlag blockInParentPartitionAddr (CPaddr (blockInParentPartitionAddr+sh1offset)) pdAddr
      HpdIsPart HblockIsMapped Hchild). destruct HPDTIfPDFlag as (_ & _ & [startBis (HstartBis & HstartBIsPDT)]).
    unfold bentryStartAddr in *. unfold entryPDT in *. rewrite HlookupBlocks0 in *. rewrite <-HblockStart in *.
    subst startBis. contradict HstartNotPDT. unfold isPDT.
    destruct (lookup startaddr (memory s0) beqAddr); try(congruence).
    destruct v; try(congruence). trivial.
  }
  assert(HstructA: StructurePointerIsKS a).
  {
    apply StructurePointerIsKSPreservedIsBuilt with s1 s0 pdAddr pdentry1 blockInParentPartitionAddr bentry
        (MAL.removeBlockFromPhysicalMPUAux blockInParentPartitionAddr realMPU) flag; trivial; intuition.
  }
  assert(multiplexerIsPDT a).
  {
    revert Hs1. apply multiplexerIsPDTPreservedIsBuilt with pdAddr pdentry1
      (MAL.removeBlockFromPhysicalMPUAux blockInParentPartitionAddr realMPU); trivial.
    destruct HpropsOr as [Heq | (Ha & _)]; auto.
  }
  assert(wellFormedFstShadowIfBlockEntry a).
  {
    revert Hs1. apply wellFormedFstShadowIfBlockEntryPreservedIsBuilt with pdAddr pdentry1
      (MAL.removeBlockFromPhysicalMPUAux blockInParentPartitionAddr realMPU); trivial.
    destruct HpropsOr as [Heq | (Ha & _)]; auto.
  }
  assert(HgetPartsEq: getPartitions multiplexer a = getPartitions multiplexer s0).
  {
    revert Hs1. apply getPartitionsEqIsBuilt with pdAddr pdentry1
      (MAL.removeBlockFromPhysicalMPUAux blockInParentPartitionAddr realMPU); trivial.
    destruct HpropsOr as [Heq | (Ha & _)]; auto.
  }
  assert(noDupPartitionTree a).
  { unfold noDupPartitionTree. rewrite HgetPartsEq. assumption. }
  assert(PDTIfPDFlag a).
  {
    revert Hs1. apply PDTIfPDFlagPreservedIsBuilt with pdAddr pdentry1
      (MAL.removeBlockFromPhysicalMPUAux blockInParentPartitionAddr realMPU); trivial.
    destruct HpropsOr as [Heq | (Ha & _)]; auto.
  }
  apply IHstatesList with pdAddr newPdEntriesList a; trivial.
  destruct HflagProps as [HstartNotPDT | HflagFalse]; auto. left. contradict HstartNotPDT.
  assert(HstartNotPDTs1: isPDT startaddr s1).
  {
    destruct HpropsOr as [Heq | (Ha & _)]; try(subst a; assumption). unfold isPDT in *. rewrite Ha in HstartNotPDT.
    simpl in *. destruct (beqAddr pdAddr startaddr) eqn:HbeqPdStart.
    - rewrite <-DTL.beqAddrTrue in HbeqPdStart. subst startaddr. rewrite HlookupAncestors1. trivial.
    - rewrite <-beqAddrFalse in *. rewrite removeDupIdentity in *; auto.
  }
  unfold isPDT in *. rewrite Hs1 in HstartNotPDTs1. simpl in *.
  destruct (beqAddr blockInParentPartitionAddr startaddr) eqn:HbeqBlockStart; try(exfalso; congruence).
  rewrite <-beqAddrFalse in *. rewrite removeDupIdentity in *; auto.
Qed.

Lemma DisjointKSEntriesPreservedIsBuiltRec s s0 statesList parentsList buildPart startaddr endaddr flag:
multiplexerIsPDT s0
-> wellFormedFstShadowIfBlockEntry s0
-> noDupPartitionTree s0
-> PDTIfPDFlag s0
-> DisjointKSEntries s0
-> (~isPDT startaddr s0 \/ flag = false)
-> isBuiltFromWriteAccessibleRec s0 s statesList parentsList buildPart startaddr endaddr flag
-> DisjointKSEntries s.
Proof.
revert s0. revert parentsList. revert buildPart. induction statesList; simpl; intros buildPart parentsList s0
  HmultIsPDT HwellSh1 HnoDupTree HPDTIfPDFlag Hdisjoint HflagProps HisBuilt.
- destruct HisBuilt as [_ Hss0Eq]. subst s. intuition.
- destruct HisBuilt as [pdAddr (newPdEntriesList & (HparentsList & (realMPU & (pdentry0 & pdentry1 &
                      (blockInParentPartitionAddr & (bentry & (newBentry & (s1 & (Hs1 & (HpropsOr
                       & (HnewB & (HlookupBlocks0 & HlookupBlocks1 & HPFlag & HblockStart & HblockEnd &
                       HpdIsPart & HblockIsMapped & HlookupParentsInit & HlookupParents1 & HlookupAncestorsInit &
                       HlookupAncestors1 & Hancestor & HbaseNotRoot & HisBuilt))))))))))))].
  assert(HflagPropsB: false = checkChild blockInParentPartitionAddr s0 (CPaddr (blockInParentPartitionAddr+sh1offset))
    \/ flag = false).
  {
    destruct HflagProps as [HstartNotPDT | HflagFalse]; auto. left.
    destruct (checkChild blockInParentPartitionAddr s0 (CPaddr (blockInParentPartitionAddr+sh1offset)))
      eqn:HcheckChild; trivial. exfalso.
    assert(Hchild: true = checkChild blockInParentPartitionAddr s0 (CPaddr (blockInParentPartitionAddr+sh1offset))
      /\ sh1entryAddr blockInParentPartitionAddr (CPaddr (blockInParentPartitionAddr+sh1offset)) s0).
    { split; auto. unfold sh1entryAddr. rewrite HlookupBlocks0. reflexivity. }
    specialize(HPDTIfPDFlag blockInParentPartitionAddr (CPaddr (blockInParentPartitionAddr+sh1offset)) pdAddr
      HpdIsPart HblockIsMapped Hchild). destruct HPDTIfPDFlag as (_ & _ & [startBis (HstartBis & HstartBIsPDT)]).
    unfold bentryStartAddr in *. unfold entryPDT in *. rewrite HlookupBlocks0 in *. rewrite <-HblockStart in *.
    subst startBis. contradict HstartNotPDT. unfold isPDT.
    destruct (lookup startaddr (memory s0) beqAddr); try(congruence).
    destruct v; try(congruence). trivial.
  }
  assert(HpropsA: DisjointKSEntries a).
  {
    apply DisjointKSEntriesPreservedIsBuilt with s1 s0 pdAddr pdentry1 blockInParentPartitionAddr bentry
        (MAL.removeBlockFromPhysicalMPUAux blockInParentPartitionAddr realMPU) flag; trivial; intuition.
  }
  assert(multiplexerIsPDT a).
  {
    revert Hs1. apply multiplexerIsPDTPreservedIsBuilt with pdAddr pdentry1
      (MAL.removeBlockFromPhysicalMPUAux blockInParentPartitionAddr realMPU); trivial.
    destruct HpropsOr as [Heq | (Ha & _)]; auto.
  }
  assert(wellFormedFstShadowIfBlockEntry a).
  {
    revert Hs1. apply wellFormedFstShadowIfBlockEntryPreservedIsBuilt with pdAddr pdentry1
      (MAL.removeBlockFromPhysicalMPUAux blockInParentPartitionAddr realMPU); trivial.
    destruct HpropsOr as [Heq | (Ha & _)]; auto.
  }
  assert(HgetPartsEq: getPartitions multiplexer a = getPartitions multiplexer s0).
  {
    revert Hs1. apply getPartitionsEqIsBuilt with pdAddr pdentry1
      (MAL.removeBlockFromPhysicalMPUAux blockInParentPartitionAddr realMPU); trivial.
    destruct HpropsOr as [Heq | (Ha & _)]; auto.
  }
  assert(noDupPartitionTree a).
  { unfold noDupPartitionTree. rewrite HgetPartsEq. assumption. }
  assert(PDTIfPDFlag a).
  {
    revert Hs1. apply PDTIfPDFlagPreservedIsBuilt with pdAddr pdentry1
      (MAL.removeBlockFromPhysicalMPUAux blockInParentPartitionAddr realMPU); trivial.
    destruct HpropsOr as [Heq | (Ha & _)]; auto.
  }
  assert(DisjointKSEntries a).
  {
    revert Hs1. apply DisjointKSEntriesPreservedIsBuilt with pdAddr pdentry1
      (MAL.removeBlockFromPhysicalMPUAux blockInParentPartitionAddr realMPU); trivial.
    destruct HpropsOr as [Heq | (Ha & _)]; auto.
  }
  apply IHstatesList with pdAddr newPdEntriesList a; trivial.
  destruct HflagProps as [HstartNotPDT | HflagFalse]; auto. left. contradict HstartNotPDT.
  assert(HstartNotPDTs1: isPDT startaddr s1).
  {
    destruct HpropsOr as [Heq | (Ha & _)]; try(subst a; assumption). unfold isPDT in *. rewrite Ha in HstartNotPDT.
    simpl in *. destruct (beqAddr pdAddr startaddr) eqn:HbeqPdStart.
    - rewrite <-DTL.beqAddrTrue in HbeqPdStart. subst startaddr. rewrite HlookupAncestors1. trivial.
    - rewrite <-beqAddrFalse in *. rewrite removeDupIdentity in *; auto.
  }
  unfold isPDT in *. rewrite Hs1 in HstartNotPDTs1. simpl in *.
  destruct (beqAddr blockInParentPartitionAddr startaddr) eqn:HbeqBlockStart; try(exfalso; congruence).
  rewrite <-beqAddrFalse in *. rewrite removeDupIdentity in *; auto.
Qed.

Lemma getMappedPaddrEqIsBuilt part s s1 s0 pdAddr pdentry1 blockInParentPartitionAddr bentry newMPU flag:
isPDT part s0
-> lookup pdAddr (memory s0) beqAddr = Some (PDT pdentry1)
-> lookup blockInParentPartitionAddr (memory s0) beqAddr = Some (BE bentry)
-> (s = s1
    \/
     s =
     {|
       currentPartition := currentPartition s1;
       memory :=
         add pdAddr
           (PDT
              {|
                structure := structure pdentry1;
                firstfreeslot := firstfreeslot pdentry1;
                nbfreeslots := nbfreeslots pdentry1;
                nbprepare := nbprepare pdentry1;
                parent := ADT.parent pdentry1;
                MPU := newMPU;
                vidtAddr := vidtAddr pdentry1
              |}) (memory s1) beqAddr
     |})
-> s1 =
      {|
        currentPartition := currentPartition s0;
        memory :=
          add blockInParentPartitionAddr
            (BE
               (CBlockEntry (read bentry) (write bentry) (exec bentry) (present bentry) flag
                  (blockindex bentry) (blockrange bentry))) (memory s0) beqAddr
      |}
-> getMappedPaddr part s = getMappedPaddr part s0.
Proof.
intros HpartIsPDT HlookupPd HlookupBlock HpropsOr Hs1.
assert(HlowerThanMax: blockindex bentry < kernelStructureEntriesNb) by (apply Hidx).
destruct (beqAddr blockInParentPartitionAddr pdAddr) eqn:HbeqBlockPdAddr.
{
  rewrite <-DTL.beqAddrTrue in HbeqBlockPdAddr. rewrite HbeqBlockPdAddr in *.
  rewrite HlookupBlock in HlookupPd. exfalso; congruence.
}
assert(HlookupPdAddrs1: lookup pdAddr (memory s1) beqAddr = Some (PDT pdentry1)).
{
  rewrite Hs1. simpl. rewrite HbeqBlockPdAddr. rewrite <-beqAddrFalse in HbeqBlockPdAddr.
  rewrite removeDupIdentity; intuition.
}
assert(HgetMappedEq: getMappedPaddr part s1 = getMappedPaddr part s0).
{
  unfold CBlockEntry in Hs1. destruct (Compare_dec.lt_dec (blockindex bentry) kernelStructureEntriesNb); try(lia).
  rewrite Hs1. apply getMappedPaddrEqBEPresentNoChangeStartNoChangeEndNoChangeEquivalence with bentry; trivial.
}
rewrite <-HgetMappedEq. destruct HpropsOr as [Hss1Eq | Hs]; try(subst s; reflexivity).
rewrite Hs. apply getMappedPaddrEqPDT with pdentry1; trivial.
Qed.

Lemma noDupMappedPaddrListPreservedIsBuilt s s1 s0 pdAddr pdentry1 blockInParentPartitionAddr bentry
newMPU flag:
noDupMappedPaddrList s0
-> multiplexerIsPDT s0
-> wellFormedFstShadowIfBlockEntry s0
-> noDupPartitionTree s0
-> PDTIfPDFlag s0
-> lookup pdAddr (memory s0) beqAddr = Some (PDT pdentry1)
