  HpropsOr Hs1 HcheckChild HpartIsPart HblockMapped Hsh1 HPDchild HchildLoc HbeqChildPartNull HbeqBCNull.
assert(HflagProp: false = checkChild blockInParentPartitionAddr s0 (CPaddr (blockInParentPartitionAddr + sh1offset))
  \/ flag = false).
{ destruct flag; auto. }
destruct (beqAddr blockInParentPartitionAddr pdAddr) eqn:HbeqBlockPdAddr.
{
  rewrite <-DTL.beqAddrTrue in HbeqBlockPdAddr. rewrite HbeqBlockPdAddr in *.
  rewrite HlookupBlock in HlookupPdAddr. exfalso; congruence.
}
