assert(blockindex bentry < kernelStructureEntriesNb) by (apply Hidx).
destruct (beqAddr blockInParentPartitionAddr (CPaddr (blockInParentPartitionAddr + sh1offset)))
   eqn:HbeqBlockBlockSh1.
{
