          by (unfold isBE; rewrite HlookupBlock; trivial).
  specialize(HwellSh1 blockInParentPartitionAddr HblockIsBE).
  rewrite <-DTL.beqAddrTrue in HbeqBlockBlockSh1. rewrite <-HbeqBlockBlockSh1 in *.
