}
assert(HgetPartsEqs1: getPartitions multiplexer s1 = getPartitions multiplexer s0).
{ revert Hs1. apply getPartitionsEqIsBuilt with pdAddr pdentry1 newMPU; auto. }
assert(HgetPartsEq: getPartitions multiplexer s = getPartitions multiplexer s1).
{ rewrite HgetPartsEqs1. revert HpropsOr Hs1. apply getPartitionsEqIsBuilt; auto. }
rewrite HgetPartsEq in *. rewrite HgetPartsEqs1 in *. assert(isPDT part s0) by (apply partitionsArePDT; trivial).
assert(HgetMappedEq: forall partition, isPDT partition s0
  -> getMappedBlocks partition s = getMappedBlocks partition s0).
{ intros partition HpartBIsPDT. revert HpropsOr Hs1. apply getMappedBlocksEqIsBuilt; auto. }
rewrite HgetMappedEq in HblockMapped; trivial. assert(Hsh1s0: sh1entryAddr block sh1entryaddr s0).
