  - rewrite <-DTL.beqAddrTrue in HbeqBlocks. subst block. rewrite HlookupBlock. unfold CBlockEntry in Hstarts1.
    assert(blockindex bentry < kernelStructureEntriesNb) by (apply Hidx).
