    - subst s. assumption.
    - rewrite Hs in HblockIsBE. simpl in *. destruct (beqAddr pdAddr block) eqn:HbeqPdBlock; try(exfalso; congruence).
      rewrite <-beqAddrFalse in *. rewrite removeDupIdentity in *; auto.
  }
  unfold isBE in *. rewrite Hs1 in Hblocks1. simpl in *.
  destruct (beqAddr blockInParentPartitionAddr block) eqn:HbeqBlocks.
  - rewrite <-DTL.beqAddrTrue in HbeqBlocks. subst block. rewrite HlookupBlock. auto.
  - rewrite <-beqAddrFalse in *. rewrite removeDupIdentity in *; auto.
}
assert(HeqRange: getAllPaddrAux [parentBlock] s = getAllPaddrAux [parentBlock] s0).
{
  assert(Heqs1: getAllPaddrAux [parentBlock] s = getAllPaddrAux [parentBlock] s1).
