  simpl in *. rewrite Heqs1 in *. rewrite Hs1 in HsceInRange. rewrite Hs1. simpl in *.
  destruct (beqAddr blockInParentPartitionAddr parentBlock) eqn:HbeqBlocks.
  - rewrite <-DTL.beqAddrTrue in HbeqBlocks. subst parentBlock. rewrite HlookupBlock. auto.
  - rewrite <-beqAddrFalse in *. rewrite removeDupIdentity; auto.
