assert(isPDT part s0) by (apply partitionsArePDT; trivial).
rewrite HgetMappedEq in *; trivial. assert(HgetChildrenEq: getChildren part s = getChildren part s0).
{ revert HpropsOr Hs1. apply getChildrenEqIsBuilt; trivial. }
rewrite HgetChildrenEq. assert(Hsh1s0: sh1entryAddr block sh1entryaddr s0).
{
  assert(Hsh1s1: sh1entryAddr block sh1entryaddr s1).
  {
    destruct HpropsOr as [Heq | Hs]; try(subst s; assumption). unfold sh1entryAddr in *. rewrite Hs in Hsh1.
    simpl in Hsh1. destruct (beqAddr pdAddr block) eqn:HbeqPdBlock; try(exfalso; congruence).
    rewrite <-beqAddrFalse in *. rewrite removeDupIdentity in *; auto.
  }
  unfold sh1entryAddr in *. rewrite Hs1 in Hsh1s1. simpl in *.
  destruct (beqAddr blockInParentPartitionAddr block) eqn:HbeqBlocks.
  - rewrite <-DTL.beqAddrTrue in HbeqBlocks. subst block. rewrite HlookupBlock. trivial.
  - rewrite <-beqAddrFalse in *. rewrite removeDupIdentity in *; auto.
}
