    destruct (beqAddr pdAddr sh1entryaddr) eqn:HbeqPartSh1; try(exfalso; congruence).
    rewrite <-beqAddrFalse in *. rewrite removeDupIdentity; auto.
  }
  rewrite Heq in *. rewrite Hs1 in HPDchild. simpl in *.
  destruct (beqAddr blockInParentPartitionAddr sh1entryaddr) eqn:HbeqBlockSh1; try(exfalso; congruence).
  rewrite <-beqAddrFalse in *. rewrite removeDupIdentity in *; auto.
}
specialize(HPDchildIsPart part block sh1entryaddr idchild HpartIsPart HblockMapped Hsh1s0 HPDchilds0 HbeqChildNull).
assumption.
Qed.

