              {|
                structure := structure pdentry1;
                firstfreeslot := firstfreeslot pdentry1;
                nbfreeslots := nbfreeslots pdentry1;
                nbprepare := nbprepare pdentry1;
                parent := ADT.parent pdentry1;
                MPU := newMPU;
