destruct Hshas0 as (HPDchilds0 & Hlocs0).
assert(isPDT part s0) by (rewrite HgetPartsEq in *; apply partitionsArePDT; trivial).
rewrite HgetMappedEq in HblockMapped; trivial. assert(In idchild (getPartitions multiplexer a)).
{
  rewrite HgetPartsEq in *.
  specialize(HPDchildIsPart part block sh1entryaddr idchild HpartIsPart HblockMapped Hsh1s0 HPDchilds0 HbeqChildNull).
  apply childrenPartitionInPartitionList with part; trivial.
}
specialize(HlocSameStartPartial HpartIsPart HblockMapped Hsh1s0 HPDchilds0 Hlocs0 HbeqChildNull HbeqBCNull).
assert(isPDT idchild s0) by (rewrite HgetPartsEq in *; apply partitionsArePDT; trivial).
rewrite HgetMappedEq; trivial. destruct HlocSameStartPartial as (HsameStart & HBCMapped). split; trivial.
intros startB Hstart. assert(Hstarts0: bentryStartAddr block startB s0).
{
  unfold bentryStartAddr. rewrite Hs1 in Hstart. simpl in *.
  destruct (beqAddr blockInParentPartitionAddr block) eqn:HbeqBlocks.
