    }
    assert(HlookupBlockChild: exists bentryChild, lookup blockChild (memory s0) beqAddr
                                                  = Some (BE bentryChild)
                                                  /\ startChild = startAddr (blockrange bentryChild)
                                                  /\ endChild = endAddr (blockrange bentryChild)).
    {
