  {
    apply AccessibleNoPDFlagPreservedIsBuilt with s1 s0 pdAddr pdentryPdAddr blockInParentPartitionAddr
      bentry (MAL.removeBlockFromPhysicalMPUAux blockInParentPartitionAddr realMPU) flag; auto.
